  /**
   * Writing more bytes than the target array can hold overruns the array and
   * triggers an ArrayIndexOutOfBoundsException.
   */
  @Test(timeout = 4000)
  public void toLittleEndianIntoArray_withLengthLargerThanArray_throwsArrayIndexOutOfBounds()  throws Throwable  {
      byte[] target = new byte[2];

      try {
        ByteUtils.toLittleEndian(target, -1L, 0, 6);
        fail("Expecting exception: ArrayIndexOutOfBoundsException");
      } catch(ArrayIndexOutOfBoundsException e) {
         verifyException("org.apache.commons.compress.utils.ByteUtils", e);
      }
  }

  /**
   * A negative length means the writing loop never runs, so the target array is
   * left untouched.
   */
  @Test(timeout = 4000)
  public void toLittleEndianIntoArray_withNegativeLength_leavesArrayUnchanged()  throws Throwable  {
      byte[] target = new byte[5];

      ByteUtils.toLittleEndian(target, 4466L, (int) (byte) -1, (int) (byte) -1);

      assertArrayEquals(new byte[] {(byte)0, (byte)0, (byte)0, (byte)0, (byte)0}, target);
  }

