  /**
   * Writing the value 0 across 8 bytes emits 8 zero (NUL) bytes to the output stream.
   */
  @Test(timeout = 4000)
  public void toLittleEndianToOutputStream_writesRequestedNumberOfBytes()  throws Throwable  {
      ByteArrayOutputStream out = new ByteArrayOutputStream();

      ByteUtils.toLittleEndian((OutputStream) out, 0L, 8);

      assertEquals(8, out.size());
      assertEquals("��������", out.toString());
