  /**
   * Writing a small value across many bytes via a DataOutput puts the value in
   * the first (least-significant) byte and zero-pads the remaining 211 bytes.
   */
  @Test(timeout = 4000)
  public void toLittleEndianToDataOutput_putsValueInFirstByteAndZeroPads()  throws Throwable  {
      ByteArrayOutputStream out = new ByteArrayOutputStream();
      DataOutputStream dataOut = new DataOutputStream(out);

      ByteUtils.toLittleEndian((DataOutput) dataOut, (long) (byte) 50, 212);

      assertEquals(212, out.size());
      // First byte is '2' (ASCII 50); the remaining 211 bytes are NUL.
      assertEquals("2�������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������", out.toString());
  }

  /**
