  public void toLittleEndianToByteConsumer_writesThroughToUnderlyingStream()  throws Throwable  {
      File file = MockFile.createTempFile("suffixes", "");
      MockPrintStream stream = new MockPrintStream(file);
      ByteUtils.OutputStreamByteConsumer consumer = new ByteUtils.OutputStreamByteConsumer(stream);

      ByteUtils.toLittleEndian((ByteUtils.ByteConsumer) consumer, (long) (byte) 77, 1);

      assertEquals(1L, file.length());
