  @Test(timeout = 4000)
  public void fromLittleEndianFromInputStream_readsAvailableByte_returnsZero()  throws Throwable  {
      byte[] data = new byte[1];
      ByteArrayInputStream in = new ByteArrayInputStream(data);

      long result = ByteUtils.fromLittleEndian((InputStream) in, 1);

      assertEquals(0L, result);
      assertEquals(0, in.available());
