  @Test(timeout = 4000)
  public void fromLittleEndianFromInputStream_notEnoughBytes_throwsIOException()  throws Throwable  {
      byte[] data = new byte[9];
      // Window of only 1 byte starting at offset 8, but 8 bytes are requested.
      ByteArrayInputStream in = new ByteArrayInputStream(data, 8, 1);

      try {
        ByteUtils.fromLittleEndian((InputStream) in, 8);
        fail("Expecting exception: IOException");
      } catch(IOException e) {
