      // Window of 2 bytes starting at offset 2; only 1 byte is read.
      ByteArrayInputStream in = new ByteArrayInputStream(data, 2, 2);
      DataInputStream dataIn = new DataInputStream(in);

      long result = ByteUtils.fromLittleEndian((DataInput) dataIn, 1);

      assertEquals(0L, result);
      assertEquals(1, in.available());
